#Requires -Version 7.0
[CmdletBinding()]
param([string]$EvidenceDir)
$ErrorActionPreference='Stop'
$ProductRoot=Split-Path -Parent (Split-Path -Parent $PSScriptRoot)
$Launcher=Join-Path $ProductRoot 'csg.ps1';$Fake=Join-Path $ProductRoot 'tests/fake-codex.ps1'
$Evidence=if($EvidenceDir){$EvidenceDir}else{Join-Path $PSScriptRoot ('evidence\'+(Get-Date -Format yyyyMMdd-HHmmss))};$State=Join-Path $Evidence state;New-Item -ItemType Directory -Force -Path $State|Out-Null
$results=[System.Collections.Generic.List[object]]::new()
function A([string]$n,[bool]$p,[string]$d){$results.Add([pscustomobject]@{name=$n;pass=$p;detail=$d});Write-Host ("[{0}] {1} - {2}"-f $(if($p){'PASS'}else{'FAIL'}),$n,$d)}
function C([string[]]$a,[hashtable]$e=@{},[int]$t=90){$s=[Diagnostics.ProcessStartInfo]::new();$s.FileName=(Get-Command pwsh).Source;$s.WorkingDirectory=$ProductRoot;$s.UseShellExecute=$false;$s.RedirectStandardOutput=$true;$s.RedirectStandardError=$true;foreach($x in @('-NoProfile','-ExecutionPolicy','Bypass','-File',$Launcher)+$a){[void]$s.ArgumentList.Add([string]$x)};$s.Environment['CSG_DATA_DIR']=$State;foreach($k in $e.Keys){$s.Environment[[string]$k]=[string]$e[$k]};$p=[Diagnostics.Process]::new();$p.StartInfo=$s;$null=$p.Start();$o=$p.StandardOutput.ReadToEndAsync();$r=$p.StandardError.ReadToEndAsync();if(!$p.WaitForExit($t*1000)){try{$p.Kill($true)}catch{};return [pscustomobject]@{ExitCode=124;StdOut=$o.Result;StdErr=$r.Result;TimedOut=$true}};return [pscustomobject]@{ExitCode=$p.ExitCode;StdOut=$o.Result;StdErr=$r.Result;TimedOut=$false}}
function E([string]$m,[int]$n,[string]$x,[string]$v='',[int]$d=0){$h=@{CSG_FAKE_MODE=$m;CSG_FAKE_SMAC_COUNT=$n;CSG_FAKE_STATE=(Join-Path $State "fake-$x.count");CSG_FAKE_DELAY_MS=$d};if($v){$h.CSG_FAKE_VARIANT=$v};Remove-Item $h.CSG_FAKE_STATE -Force -ErrorAction SilentlyContinue;return $h}
function LastRow(){ $z=Get-Rows; return @($z | Select-Object -Last 1) }
function Get-Rows{if(!(Test-Path (Join-Path $State stats.jsonl))){return @()};$z=@();foreach($l in Get-Content (Join-Path $State stats.jsonl)){try{$z+=($l|ConvertFrom-Json)}catch{}};return $z}
function Ev([string]$n,$x){Set-Content (Join-Path $Evidence "$n.txt") -Value (@("exit=$($x.ExitCode)",'--- stdout ---',$x.StdOut,'--- stderr ---',$x.StdErr)-join "`r`n") -Encoding utf8}

$cfg=Get-Content (Join-Path $ProductRoot csg.config.json)-Raw|ConvertFrom-Json;A 'A 默认参数' ([int]$cfg.attemptsPerRound -eq 100 -and [int]$cfg.cooldownSeconds -eq 1800) "attempts=$($cfg.attemptsPerRound), cooldown=$($cfg.cooldownSeconds)"
$x=C @('run','round A','--codex-cmd',$Fake,'--attempts-per-round','5','--cooldown-seconds','2','--backoff-base-seconds','0','--max-rounds','2') (E smac-then-success 5 a);Ev A_round $x;$q=LastRow;A 'A 等价边界冷却' ($x.ExitCode -eq 0 -and $q.totalAttempts -eq 6 -and ([regex]::Matches($x.StdOut,'轮耗尽')).Count -ge 1) "attempts=$($q.totalAttempts)"
$x=C @('run','round B','--codex-cmd',$Fake,'--attempts-per-round','5','--cooldown-seconds','1','--backoff-base-seconds','0','--max-rounds','3') (E smac-then-success 5 b);Ev B_round $x;$q=LastRow;A 'B 跨轮成功' ($x.ExitCode -eq 0 -and $q.totalAttempts -eq 6 -and $q.rounds -eq 2) "attempts=$($q.totalAttempts), rounds=$($q.rounds)"
$w=Join-Path $State '[Lilith] test 中文\work folder';New-Item -ItemType Directory -Force -Path $w|Out-Null;$x=C @('run','path','--cd',$w,'--codex-cmd',$Fake,'--attempts-per-round','1','--cooldown-seconds','0','--backoff-base-seconds','0') (E hash 0 c);Ev C_path $x;$rd=Get-ChildItem (Join-Path $State runs)-Directory|Sort-Object LastWriteTime -Descending|Select-Object -First 1;A 'C 特殊路径' ($x.ExitCode -eq 0 -and (Test-Path (Join-Path $rd.FullName 'status.json')) -and (Test-Path (Join-Path $rd.FullName 'attempt-001-001\stdout.log'))) 'run/cd/log正常'
$missing=Join-Path $State 'does-not-exist';$x=C @('run','bad cd','--cd',$missing,'--codex-cmd',$Fake) (E hash 0 cm);Ev L_bad_cd $x;A 'L 不存在cd清晰报错' ($x.ExitCode -eq 2 -and ($x.StdOut+$x.StdErr) -match '工作目录不存在或不可用' -and -not (Test-Path $missing)) '不创建缺失目录'
$p=@'
双引号 " 单引号 ' 换行
emoji 🚀 dollar $ backtick ` percent % bang !
'@;$h=[Security.Cryptography.SHA256]::Create();try{$sha=([BitConverter]::ToString($h.ComputeHash([Text.Encoding]::UTF8.GetBytes($p)))).Replace('-','').ToLowerInvariant()}finally{$h.Dispose()};$x=C @('run',$p,'--codex-cmd',$Fake,'--attempts-per-round','1','--cooldown-seconds','0','--backoff-base-seconds','0') ((E hash 0 d)+@{CSG_FAKE_EXPECT_HASH=$sha});Ev D_prompt $x;A 'D prompt字节' ($x.ExitCode -eq 0 -and ($x.StdOut+$x.StdErr)-notmatch 'PROMPT_HASH_MISMATCH') 'SHA256一致'
$jobs=@();foreach($n in 'e1','e2'){$en=E hash 0 $n 300;$s=[Diagnostics.ProcessStartInfo]::new();$s.FileName=(Get-Command pwsh).Source;$s.WorkingDirectory=$ProductRoot;$s.UseShellExecute=$false;$s.RedirectStandardOutput=$true;$s.RedirectStandardError=$true;foreach($z in @('-NoProfile','-ExecutionPolicy','Bypass','-File',$Launcher,'run',$n,'--codex-cmd',$Fake,'--attempts-per-round','1','--cooldown-seconds','0','--backoff-base-seconds','0')){[void]$s.ArgumentList.Add([string]$z)};$s.Environment['CSG_DATA_DIR']=$State;foreach($k in $en.Keys){$s.Environment[$k]=[string]$en[$k]};$p0=[Diagnostics.Process]::new();$p0.StartInfo=$s;$null=$p0.Start();$jobs+=$p0};foreach($j in $jobs){$j.WaitForExit(30000)|Out-Null};$q=Get-Rows;A 'E 并发stats' (($jobs|Where-Object ExitCode -eq 0).Count -eq 2 -and @($q|Where-Object success).Count -ge 2) "rows=$($q.Count)"
Add-Content -LiteralPath (Join-Path $State 'stats.jsonl') -Value '{bad';Add-Content -LiteralPath (Join-Path $State 'stats.jsonl') -Value '{"half":'; $sf=(Get-ChildItem (Join-Path $State runs)-Directory|Select-Object -First 1).FullName+'\status.json';Set-Content $sf '{"runId":"broken"' -Encoding utf8;$x=C @('stats');$y=C @('status');Ev F_stats $x;A 'F 坏行跳过' ($x.ExitCode -eq 0 -and $y.ExitCode -eq 0 -and ($x.StdOut+$x.StdErr+$y.StdOut+$y.StdErr) -match '损坏') '跳过并提示'
$dl=(Get-Date).AddSeconds(1).ToString('o');$x=C @('run','deadline','--codex-cmd',$Fake,'--attempts-per-round','1','--cooldown-seconds','5','--backoff-base-seconds','0','--deadline',$dl) (E always-smac 0 g);Ev G_deadline $x;$q=LastRow;A 'G 冷却中deadline' ($x.ExitCode -eq 3 -and !$q.success) "exit=$($x.ExitCode)"
$x=C @('run','auth','--codex-cmd',$Fake,'--attempts-per-round','3','--cooldown-seconds','0','--backoff-base-seconds','0') (E non-capacity 0 h);$hs=C @('status');Ev H_noncapacity $x;$q=LastRow;A 'H 非容量错误' ($x.ExitCode -eq 2 -and $q.smacCount -eq 0 -and ($hs.StdOut+$hs.StdErr)-match 'authentication failed') 'exit2/no SMAC/status可见'
$src=Get-Content $Launcher -Raw;A 'I Ctrl+C静态审查' ($src-match 'CancelKeyPress' -and $src-match 'Kill\(\$true\)' -and $src-match '130') '信号/递归清理存在，未伪终端实测'
Remove-Item (Join-Path $ProductRoot 'install-state.json') -Force -ErrorAction SilentlyContinue;$installHome=Join-Path $State 'install home';New-Item -ItemType Directory -Force -Path $installHome|Out-Null;$before=[Environment]::GetEnvironmentVariable('Path','User');try{$i=C @('install') @{USERPROFILE=$installHome};$i2=C @('install') @{USERPROFILE=$installHome};$bin=Join-Path $installHome bin;$up=[Environment]::GetEnvironmentVariable('Path','User');$cnt=@($up-split ';'|Where-Object {$_ -eq $bin}).Count;$u=C @('uninstall') @{USERPROFILE=$installHome};$u2=C @('uninstall') @{USERPROFILE=$installHome};$after=[Environment]::GetEnvironmentVariable('Path','User');A 'J install幂等回滚' ($i.ExitCode-eq 0-and$i2.ExitCode-eq 0-and$u.ExitCode-eq 0-and$u2.ExitCode-eq 0-and$cnt-eq 1-and$after-eq$before) "entries=$cnt, restored=$($after-eq$before)"}finally{[Environment]::SetEnvironmentVariable('Path',$before,'User');Remove-Item $installHome -Recurse -Force -ErrorAction SilentlyContinue;Remove-Item (Join-Path $ProductRoot install-state.json) -Force -ErrorAction SilentlyContinue}
$empty=Join-Path $State empty;$x=C @('status') @{CSG_DATA_DIR=$empty};$del=Get-ChildItem (Join-Path $State runs)-Directory|Select-Object -Last 1;if($del){Remove-Item $del.FullName -Recurse -Force};$y=C @('status');A 'K 空历史/删除run' ($x.ExitCode-eq 0-and$y.ExitCode-eq 0) 'status稳定'
$x=C @('run','security','--codex-cmd',$Fake,'--attempts-per-round','1','--cooldown-seconds','0','--backoff-base-seconds','0') (E secret-output 0 l);$all=(Get-ChildItem (Join-Path $State runs)-Recurse -File|Get-Content -Raw)-join "`n";$all += Get-Content (Join-Path $State stats.jsonl)-Raw;A 'L 日志脱敏' ($all-notmatch 'sk-super-secret|super-secret-value') 'token未落日志或stats'
$x=C @('run','quoted smac','--codex-cmd',$Fake,'--attempts-per-round','5','--cooldown-seconds','0','--backoff-base-seconds','0') (E success-with-smac-text 0 m);$q=LastRow;A 'M 成功引用SMAC不误判' ($x.ExitCode-eq 0-and$q.totalAttempts-eq 1-and$q.smacCount-eq 0) "attempts=$($q.totalAttempts), smac=$($q.smacCount)"
$n1=C @('run','v1','--codex-cmd',$Fake,'--attempts-per-round','1','--cooldown-seconds','0','--backoff-base-seconds','0','--max-rounds','1') (E smac-variant 1 n1 upper);$n2=C @('run','v2','--codex-cmd',$Fake,'--attempts-per-round','1','--cooldown-seconds','0','--backoff-base-seconds','0','--max-rounds','1') (E smac-variant 1 n2 crlf);$n3=C @('run','disk','--codex-cmd',$Fake,'--attempts-per-round','1','--cooldown-seconds','0','--backoff-base-seconds','0','--max-rounds','1') (E disk-capacity 0 n3);$z=Get-Rows;$q=@($z|Select-Object -Last 3);A 'N 大小写空白/排除无关capacity' ($n1.ExitCode-eq 2-and$n2.ExitCode-eq 2-and$n3.ExitCode-eq 2-and$q[0].smacCount-eq 1-and$q[1].smacCount-eq 1-and$q[2].smacCount-eq 0) "smac=$($q[0].smacCount),$($q[1].smacCount),$($q[2].smacCount)"
$sum=[ordered]@{generatedAt=(Get-Date).ToString('o');passed=@($results|Where-Object pass).Count;failed=@($results|Where-Object {-not $_.pass}).Count;tests=@($results)};$sum|ConvertTo-Json -Depth 8|Set-Content (Join-Path $Evidence summary.json) -Encoding utf8;$md=@("# CSG 对抗性测试证据","","通过：$($sum.passed) / $($results.Count)");foreach($t in $results){$md+="- [$([string]::new($(if($t.pass){'x'}else{' '})))] $($t.name)：$($t.detail)"};Set-Content (Join-Path $Evidence summary.md) ($md-join "`r`n") -Encoding utf8;if($sum.failed){exit 1}else{exit 0}








